mapper.delete:
DELETE FROM kb_data_sources
  WHERE data_source_id = #{dataSourceId}
    AND kb_id IN (SELECT id FROM knowledge_bases WHERE workspace_id = #{workspaceId})

mapper.select:
SELECT 1 FROM data_source_grants g
  JOIN knowledge_bases kb ON kb.workspace_id = g.workspace_id
 WHERE kb.id = #{kbId} AND g.data_source_id = #{dataSourceId}
